WITH filtered_shipments AS (SELECT * FROM shipments WHERE carrier != 'Flash'), shipped_year_summary AS (SELECT YEAR(shipped_date) AS shipped_year, carrier, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(status))) AS status_values FROM filtered_shipments GROUP BY YEAR(shipped_date), carrier) SELECT shipped_year, carrier, status_values FROM shipped_year_summary ORDER BY status_values, carrier DESC, shipped_year LIMIT 50;
